# Kriter tanımları: (id, label, threshold_str, weight, importance)
CANSLIM_CRITERIA = [
    ('eps_qoq',    'EPS QoQ Büyüme',    '>=20%',    3, 'critical'),
    ('sma200',     'SMA200 Üzerinde',   'P>SMA200', 3, 'critical'),
    ('market',     'M Kriteri',         'Güçlü',    3, 'critical'),
    ('rev_growth', 'Gelir Büyümesi',    '>=15%',    2, 'important'),
    ('roe',        'ROE',               '>=15%',    2, 'important'),
    ('gross_mg',   'Brüt Marjin',       '>=40%',    2, 'important'),
    ('sma50',      'SMA50 Üzerinde',    'P>SMA50',  2, 'important'),
    ('52w',        '52H Yakınlık',      '>=75%',    2, 'important'),
    ('net_mg',     'Net Marjin',        '>=10%',    1, 'support'),
    ('de',         'Borç/Özkaynak',     '<=1.0',    1, 'support'),
    ('cr',         'Current Ratio',     '>=1.5',    1, 'support'),
    ('pe',         'P/E',               '<=60',     1, 'support'),
    ('mktcap',     'Piyasa Değeri',     '>=1B',     1, 'support'),
    ('rel_vol',    'Göreceli Hacim',    '>=0.8x',   1, 'support'),
    ('avg_vol',    'Ort. Hacim',        '>=500K',   1, 'support'),
    ('inst_own',   'Kurumsal Sahip.',   '>=40%',    1, 'support'),
]
MAX_WEIGHTED_SCORE = sum(c[3] for c in CANSLIM_CRITERIA)

def canslim_score(ticker, info, hist, market_ok=True):
    cr_res = {}
    closes = hist['Close'].dropna() if not hist.empty else None
    if closes is None or len(closes) < 50:
        return None, None, {}
    price = float(closes.iloc[-1])

    def safe(key, d=None):
        try:
            v = info.get(key)
            return float(v) if v is not None else d
        except: return d

    def add(cid, val_str, passed, limit):
        cr_res[cid] = {'val': val_str, 'passed': passed, 'limit': limit}

    # 1. EPS QoQ [ZORUNLU]
    v = safe('earningsQuarterlyGrowth')
    if v is not None:
        pct = round(v*100,1)
        add('eps_qoq', f'{pct:+.1f}%', pct>=20, '>=20%')

    # 2. Rev Growth [ÖNEMLI]
    v = safe('revenueGrowth')
    if v is not None:
        pct = round(v*100,1)
        add('rev_growth', f'{pct:+.1f}%', pct>=15, '>=15%')

    # 3. ROE [ÖNEMLI]
    v = safe('returnOnEquity')
    if v is not None:
        pct = round(v*100,1)
        add('roe', f'{pct:.1f}%', pct>=15, '>=15%')

    # 4. Gross Margin [ÖNEMLI]
    v = safe('grossMargins')
    if v is not None:
        pct = round(v*100,1)
        add('gross_mg', f'{pct:.1f}%', pct>=40, '>=40%')

    # 5. Net Margin [DESTEK]
    v = safe('profitMargins')
    if v is not None:
        pct = round(v*100,1)
        add('net_mg', f'{pct:.1f}%', pct>=10, '>=10%')

    # 6. D/E [DESTEK]
    v = safe('debtToEquity')
    if v is not None:
        val = round(v/100, 2)
        add('de', str(val), val<=1.0, '<=1.0')

    # 7. Current Ratio [DESTEK]
    v = safe('currentRatio')
    if v is not None:
        add('cr', str(round(v,2)), v>=1.5, '>=1.5')

    # 8. P/E [DESTEK]
    v = safe('trailingPE')
    if v is not None and v > 0:
        add('pe', str(round(v,1)), v<=60, '<=60')

    # 9. Market Cap [DESTEK]
    v = safe('marketCap')
    if v is not None:
        s = f'${v/1e9:.1f}B' if v>=1e9 else f'${v/1e6:.0f}M'
        add('mktcap', s, v>=1e9, '>=1B')

    # 10. 52W [ÖNEMLI]
    h52 = safe('fiftyTwoWeekHigh')
    if h52 and price > 0:
        pct = round(price/h52*100, 1)
        add('52w', f'{pct:.1f}%', pct>=75, '>=75%')

    # 11. SMA50 [ÖNEMLI]
    if len(closes) >= 50:
        sma50 = float(closes.tail(50).mean())
        dist = round((price-sma50)/sma50*100, 1)
        add('sma50', f'${round(sma50,2)} ({dist:+.1f}%)', price>sma50, 'P>SMA50')

    # 12. SMA200 [ZORUNLU]
    if len(closes) >= 200:
        sma200 = float(closes.tail(200).mean())
        dist = round((price-sma200)/sma200*100, 1)
        add('sma200', f'${round(sma200,2)} ({dist:+.1f}%)', price>sma200, 'P>SMA200')

    # 13. Rel Vol [DESTEK]
    if len(hist) >= 20:
        vols = hist['Volume'].dropna()
        avg20 = float(vols.tail(20).mean())
        last = float(vols.iloc[-1])
        rv = round(last/avg20, 2) if avg20 > 0 else 0
        add('rel_vol', f'{rv}x', rv>=0.8, '>=0.8x')

    # 14. Avg Vol [DESTEK]
    v = safe('averageVolume')
    if v is not None:
        s = f'{int(v/1000)}K' if v<1e6 else f'{v/1e6:.1f}M'
        add('avg_vol', s, v>=500000, '>=500K')

    # 15. Inst Own [DESTEK]
    v = safe('institutionsPercentHeld')
    if v is not None:
        pct = round(v*100, 1)
        add('inst_own', f'{pct:.1f}%', pct>=40, '>=40%')

    # 16. M Kriteri [ZORUNLU]
    add('market', 'Güçlü' if market_ok else 'Zayıf', market_ok, 'Güçlü')

    # Ağırlıklı skor
    weighted = sum(c[3] for c in CANSLIM_CRITERIA if cr_res.get(c[0],{}).get('passed'))
    raw = sum(1 for c in CANSLIM_CRITERIA if cr_res.get(c[0],{}).get('passed'))
    return weighted, raw, cr_res


def run_canslim_screener(market_data, watchlist, portfolio):
    """CANSLIM screener - tüm tech universe + watchlist/portfolio"""
    import yfinance as yf2
    
    # M kriteri kontrol
    md = market_data or {}
    sp = md.get('SP500', {})
    nas = md.get('NASDAQ', {})
    market_ok = sp.get('above200', False) and nas.get('above200', False)
    
    results = []
    
    # Tüm hisseler: universe + watchlist + portfolio (tekrarsız)
    all_tickers = list(set(TECH_UNIVERSE + watchlist + portfolio))
    
    print(f'  {len(all_tickers)} hisse taranıyor...')
    
    for ticker in all_tickers:
        try:
            tk = yf2.Ticker(ticker)
            hist = tk.history(period='1y', interval='1d')
            info = tk.info or {}
            
            if hist.empty or len(hist) < 50:
                continue
            
            weighted_score, raw_score, criteria_results = canslim_score(ticker, info, hist, market_ok)
            if weighted_score is None:
                continue
            
            closes = hist['Close'].dropna()
            price = round(float(closes.iloc[-1]), 2)
            prev = round(float(closes.iloc[-2]), 2) if len(closes) > 1 else price
            change = round((price - prev) / prev * 100, 2)
            
            # Anlık fiyat
            rt = get_realtime_price(ticker, FINNHUB_KEY)
            if rt and rt['price'] > 0:
                price = rt['price']
                change = rt['change']
            
            sector = info.get('sector', 'Technology')
            name = info.get('shortName', ticker)
            
            results.append({
                'ticker': ticker,
                'name': name,
                'price': price,
                'change': change,
                'score': raw_score,
                'weighted_score': weighted_score,
                'max_score': 16,
                'max_weighted': MAX_WEIGHTED_SCORE,
                'pct': round(weighted_score/MAX_WEIGHTED_SCORE*100),
                'criteria': criteria_results,
                'sector': sector,
                'in_watchlist': ticker in watchlist,
                'in_portfolio': ticker in portfolio,
                'passed': weighted_score >= 19  # ~%70 ağırlıklı eşik
            })
        except Exception as e:
            continue
    
    # Skora göre sırala
    results.sort(key=lambda x: x['score'], reverse=True)
    print(f'  {len([r for r in results if r["passed"]])} hisse CANSLIM geçti (ağırlıklı ≥%70)')
    return results


